(2, 'email_change_pass_user_action_created', '', 'Hello\r\n\r\nOn {0} at {1} you have requested to have you password for the domain www.compbet.com emailed to you.\r\n\r\nTo change your password, please visit this page:\r\n\r\n{2}/cs/uzivatel-akce?action={3}\r\n\r\nIf the above link can not be clicked, or if it is not working properly please do copy and paste it into the address bar of your web browser.\r\n\r\nIn case you have not requested to have your password emailed to you, you can ignore this email.\r\n\r\nWith wishes of rich winnings\r\n\r\nteam BetService', 0, 6647),
(1, 'email_change_pass_user_action_created', '', 'Dobrý den\r\n\r\nDne {0} v {1} jste si vyžádal/a zaslání hesla k doméně www.compbet.com.\r\n\r\nPro změnu hesla prosím navštivte tuto stránku:\r\n\r\n{2}/cs/uzivatel-akce?action={3}\r\n\r\n\r\nPokud nebudete automaticky přesměrován/a na tuto stránku po kliknutí na link, můžete jej vložit do adresového pole prohlížeče pomocí funkcí kopírovat a vložit.\r\n\r\nV případě, že jste o zaslání nového hesla nepožádal/a, můžete tento mail ignorovat.\r\n\r\n\r\nS pozdravem a přáním štěstí ve hře,\r\n\r\ntým BetService', 0, 6647),
(16, 'email_change_pass_user_action_created', '', 'email translation to slovak missing', 0, 6647),
