(2, 'dep_with_text', '', '', 0, 6721),
(1, 'dep_with_text', '', '<br />\r\nVictoria-Tip, a.s. se snaží nabídnout svým zákazníkům ty nejlepší platební metody. Kompletní seznam všech platebních metod najdete zde. \r\n<br />\r\n\r\n<h3>Platební metody</h3>\r\n\r\n<h4>Bankovní převod</h4>\r\nBankovní převod je nejrozšířenější platební metodou. Peníze se převádějí přímo z vašeho bankovního účtu.\r\n\r\n\r\n<h4>Platební karta</h4>\r\n\r\n<em>Visa/Visa Elektron, MasterCard</em>\r\n\r\n<br />\r\n\r\nPlatba platební kartou je v současnosti nejvýhodnějším způsobem. Jsou celosvětově známé značky, které používají nejmodernější platební a bezpečnostní technologie.\r\n\r\n\r\n<h4>Na pobočce</h4>\r\n\r\nNa každé z našich provozoven (slovo provozoven odkaz na seznam provozoven) si můžete dobít Váš účet. Stačí mít jen u sebe registrační kartu (nevím,co budou dostávat) a hotovost, kterou chcete vložit na Váš účet.', 0, 6721),
