DROP TABLE IF EXISTS vic_main.ptmp;

CREATE TEMPORARY TABLE vic_main.ptmp(
 `index_pole` varchar(128) NOT NULL DEFAULT '' PRIMARY KEY,
 `preklad_id` int(11) unsigned NOT NULL
) DEFAULT CHARSET=utf8 COLLATE 'utf8_general_ci';

START TRANSACTION;

INSERT INTO vic_main.ptmp(preklad_id, index_pole)
 SELECT (@i:=@i+1) AS i, p.`index_pole`
 FROM (SELECT @i:=0) AS i, (SELECT index_pole FROM `vic_main`.`preklady` GROUP BY index_pole) p;

UPDATE vic_main.preklady p
 JOIN vic_main.ptmp t
 ON p.index_pole=t.index_pole
 SET p.preklad_id=t.preklad_id;

COMMIT;

DROP TABLE vic_main.ptmp;
